_SMS_OTP_TTL_MINUTES = 10
_SMS_OTP_MAX_ATTEMPTS = 3
_TWILIO_VERIFY_SID = os.environ.get("TWILIO_VERIFY_SID", "")

def _get_twilio_verify_client():
    """Get Twilio Verify service (uses pre-approved channels, no A2P campaign needed)."""
    try:
        from twilio.rest import Client as _TwilioClient
        _sid = os.environ.get("TWILIO_ACCOUNT_SID", "")
        _tok = os.environ.get("TWILIO_AUTH_TOKEN", "")
        if _sid and _tok and _TWILIO_VERIFY_SID:
            return _TwilioClient(_sid, _tok).verify.v2.services(_TWILIO_VERIFY_SID)
    except Exception as e:
        print(f"[Admin] Twilio Verify init error: {e}")
    return None
# NOTE: Global state dicts (ACTIVE_TOKENS, connected_coaches, connected_clients)
# are mutated from a single asyncio event loop, so no explicit lock is needed
# for asyncio (single-threaded). File I/O uses fcntl.flock for safety.
TOKEN_TTL_HOURS = 24
_TOKEN_REDIS_TTL_SECONDS = int(TOKEN_TTL_HOURS * 3600 * 1.1)  # 10% buffer over in-memory

# Centralized Redis configuration — validated on startup
_REDIS_CONFIG = {
    "host": os.environ.get("REDIS_HOST", "redis"),
    "port": int(os.environ.get("REDIS_PORT", "6379")),
    "password": os.environ.get("REDIS_PASSWORD"),
    "key_prefix": os.environ.get("REDIS_KEY_PREFIX", "nate"),
    "env": os.environ.get("ENVIRONMENT", "prod"),
}

def _redis_token_key(token: str) -> str:
    """Build a namespaced Redis key for a token."""
    return f"{_REDIS_CONFIG['key_prefix']}:{_REDIS_CONFIG['env']}:auth:{token}"

# Sync Redis client for cross-container token sharing (bridge → backend).
# Uses synchronous redis.Redis with asyncio.to_thread() to avoid
# redis-py 5.x async connection pool timeouts inside the websockets event loop.
_token_redis_sync = None

_token_redis_init_done = False
_token_redis_health_fail_count = 0

async def _init_token_redis_async(**_kw):
    """Initialize a sync Redis client for token sharing.

    Uses synchronous redis.Redis to avoid redis-py 5.x async connection
    pool timeouts inside the bridge's websockets event loop.  Resolves
    the hostname to an IP first to avoid blocking DNS in the event loop.
    """
    global _token_redis_sync, _token_redis_init_done
    if _token_redis_sync is not None:
        return
    _token_redis_init_done = True
    try:
        import redis as sync_redis
        import socket as _socket
        host = _REDIS_CONFIG["host"]
        port = _REDIS_CONFIG["port"]
        password = _REDIS_CONFIG["password"]
        try:
            resolved_ip = _socket.gethostbyname(host)
        except _socket.gaierror:
            resolved_ip = host
        client = sync_redis.Redis(
            host=resolved_ip, port=port, password=password,
            decode_responses=True,
            socket_connect_timeout=5, socket_timeout=5,
        )
        client.ping()
        _token_redis_sync = client
        print(f"[*] Token-sharing Redis connected ({host} → {resolved_ip})", flush=True)
    except Exception as e:
        print(f"[!] Token-sharing Redis unavailable ({e})", flush=True)
        _token_redis_sync = None

BALANCE_SYNC_CHANNEL = "nate:balance_sync"
USER_RELOAD_CHANNEL = "nate:user_reload"
REGISTRY_RELOAD_CHANNEL = "nate:registry_reload"
PAYMENT_CONFIRMED_CHANNEL = "nate:payment_confirmed"  # QUANTUM-CRYSTAL-ARCH


def _cache_sync_blocking_listener():
    """Blocking Redis pub/sub listener (runs in a dedicated thread).

    Listens on three channels:
      - nate:balance_sync — patches a single user's token_balance in cache
      - nate:user_reload  — reloads a specific user from PostgreSQL into cache
      - nate:registry_reload — triggers a full registry reload from PG

    This prevents the bridge cache from holding stale data at 3,000+ users.
    """
    import time as _time
    _time.sleep(5)
    while True:
        try:
            import redis as sync_redis
            import socket as _socket
            host = _REDIS_CONFIG["host"]
            port = _REDIS_CONFIG["port"]
            password = _REDIS_CONFIG["password"]
            try:
                resolved_ip = _socket.gethostbyname(host)
            except _socket.gaierror:
                resolved_ip = host
            client = sync_redis.Redis(
                host=resolved_ip, port=port, password=password,
                decode_responses=True,
                socket_connect_timeout=5,
            )
            client.ping()
            pubsub = client.pubsub()
            pubsub.subscribe(BALANCE_SYNC_CHANNEL, USER_RELOAD_CHANNEL, REGISTRY_RELOAD_CHANNEL, PAYMENT_CONFIRMED_CHANNEL)
            _cache_sync_blocking_listener._retry = 0
            print(f"[*] Cache sync listener subscribed to balance_sync + user_reload + registry_reload + payment_confirmed", flush=True)

            for message in pubsub.listen():
                if message["type"] != "message":
                    continue
                channel = message.get("channel", "")
                try:
                    if channel == BALANCE_SYNC_CHANNEL:
                        _handle_balance_sync(message["data"])
                    elif channel == USER_RELOAD_CHANNEL:
                        _handle_user_reload(message["data"])
                    elif channel == REGISTRY_RELOAD_CHANNEL:
                        _handle_registry_reload()
                    elif channel == PAYMENT_CONFIRMED_CHANNEL:
                        _handle_payment_confirmed(message["data"])
                except Exception as e:
                    print(f"[!] Cache sync message error on {channel}: {e}", flush=True)

        except Exception as e:
            _cache_sync_retry = getattr(_cache_sync_blocking_listener, '_retry', 0)
            base_delay = min(5 * (2 ** _cache_sync_retry), 120)
            import random
            jitter = random.uniform(0, base_delay * 0.2)
            delay = base_delay + jitter
            _cache_sync_blocking_listener._retry = min(_cache_sync_retry + 1, 8)
            print(f"[!] Cache sync listener error: {e} — retrying in {delay:.0f}s (attempt {_cache_sync_retry + 1})", flush=True)
            _time.sleep(delay)


def _handle_balance_sync(raw_data: str):
    """Patch a single user's token_balance in the in-memory cache."""
    data = json.loads(raw_data)
    username = data.get("username")
    new_balance = int(data.get("token_balance", 0))
    if not username:
        return
    for k, v in _registry_cache.items():
        if k.startswith("_"):
            continue
        p = v.get("profile", {})
        uname = (v.get("credentials", {}) or {}).get("username", "")
        if uname == username or p.get("username") == username:
            p["token_balance"] = new_balance
            print(f"[BALANCE SYNC] {username} → {new_balance:,} tokens (cache patched)", flush=True)
            return
    print(f"[BALANCE SYNC] {username} not found in cache — will sync on next login", flush=True)


def _handle_user_reload(raw_data: str):
    """Reload a single user from PostgreSQL into the in-memory cache.

    This is the key mechanism for preventing stale cache at scale.
    When any backend endpoint modifies a user in PG, it publishes:
        {"username": "some_user"}
    The bridge then reads the fresh row from PG and replaces the cache entry.
    """
    global _registry_cache
    data = json.loads(raw_data)
    username = data.get("username")
    if not username or not _pg_user_store or not _pg_user_store.is_ready:
        return

    import asyncio
    try:
        loop = asyncio.get_running_loop()
    except RuntimeError:
        loop = None

    async def _do_reload():
        result = await _pg_user_store.reload_user(username)
        if result:
            reg_key, entry = result
            _registry_cache[reg_key] = entry
            print(f"[USER RELOAD] {username} → cache refreshed from PG", flush=True)
        else:
            print(f"[USER RELOAD] {username} not found in PG", flush=True)

    if loop and loop.is_running():
        loop.call_soon_threadsafe(lambda: loop.create_task(_do_reload()))
    else:
        import concurrent.futures
        new_loop = asyncio.new_event_loop()
        try:
            new_loop.run_until_complete(_do_reload())
        finally:
            new_loop.close()


def _handle_registry_reload():
    """Trigger a full registry reload from PostgreSQL."""
    global _registry_cache
    if not _pg_user_store or not _pg_user_store.is_ready:
        return
    print("[REGISTRY RELOAD] Full reload triggered via Redis", flush=True)

    import asyncio
    async def _do_full_reload():
        global _registry_cache
        loaded = await _pg_user_store._load_all_from_pg()
        if loaded:
            _registry_cache = loaded
            print(f"[REGISTRY RELOAD] Reloaded {len(loaded)} entries from PG", flush=True)

    try:
        loop = asyncio.get_running_loop()
        loop.call_soon_threadsafe(lambda: loop.create_task(_do_full_reload()))
    except RuntimeError:
        new_loop = asyncio.new_event_loop()
        try:
            new_loop.run_until_complete(_do_full_reload())
        finally:
            new_loop.close()


def _handle_payment_confirmed(raw_data: str):  # QUANTUM-CRYSTAL-ARCH
    """Push payment confirmation to connected client via WebSocket."""
    data = json.loads(raw_data)
    username = data.get("username", "")
    if not username:
        return
    hw_id = None
    for k, v in _registry_cache.items():
        if k.startswith("_"):
            continue
        if (v.get("credentials", {}) or {}).get("username", "") == username or v.get("profile", {}).get("username") == username:
            hw_id = v.get("profile", {}).get("hardware_id", "")
            break
    if not hw_id:
        return

    ws = connected_clients.get(hw_id) or connected_coaches.get(hw_id)
    if not ws:
        return

    import asyncio
    msg = json.dumps({"type": "payment_confirmed", "payment_type": data.get("type", ""), "plan": data.get("plan", ""), "tokens_added": data.get("tokens_added", 0)})
    try:
        loop = asyncio.get_running_loop()
        loop.call_soon_threadsafe(lambda: loop.create_task(ws.send(msg)))
    except RuntimeError:
        pass
    print(f"[PAYMENT CONFIRMED] Pushed to {username} ({hw_id[:8]}...)", flush=True)


async def _balance_sync_listener():
    """Start the blocking Redis pub/sub listener in a daemon thread."""
    import threading
    t = threading.Thread(target=_cache_sync_blocking_listener, daemon=True, name="cache_sync")
    t.start()


async def _token_redis_health_loop():
    """Periodic health ping for the token Redis client with exponential backoff.

    Normal interval: 60s. On failure, backs off from 5s to 120s with jitter
    before attempting reconnection.
    """
    import random
    global _token_redis_sync, _token_redis_health_fail_count
    while True:
        if _token_redis_health_fail_count > 0:
            base_delay = min(5 * (2 ** min(_token_redis_health_fail_count - 1, 6)), 120)
            jitter = random.uniform(0, base_delay * 0.2)
            await asyncio.sleep(base_delay + jitter)
        else:
            await asyncio.sleep(60)
        if _token_redis_sync is not None:
            try:
                _token_redis_sync.ping()
                if _token_redis_health_fail_count > 0:
                    print(f"[*] Token Redis health recovered after {_token_redis_health_fail_count} failures", flush=True)
                    _token_redis_health_fail_count = 0
            except Exception as e:
                _token_redis_health_fail_count += 1
                print(f"[!] Token Redis health ping failed (attempt {_token_redis_health_fail_count}): {e}", flush=True)
                _token_redis_sync = None
                try:
                    await _init_token_redis_async()
                    if _token_redis_sync:
                        print(f"[*] Token Redis reconnected after health failure", flush=True)
                except Exception:
                    pass
        else:
            try:
                await _init_token_redis_async()
                if _token_redis_sync:
                    print(f"[*] Token Redis connected (was previously unavailable)", flush=True)
                    _token_redis_health_fail_count = 0
            except Exception:
                pass

# Per-IP connection limiting
_connections_per_ip: dict = {}  # ip -> count
MAX_CONNECTIONS_PER_IP = int(os.environ.get("MAX_CONNECTIONS_PER_IP", "20"))  # SOVEREIGN-VOICE — configurable for load testing

# Per-connection message rate limiting
MSG_RATE_LIMIT_WINDOW = 60  # 1 minute
MSG_RATE_LIMIT_MAX = 120    # max messages per minute
AI_RATE_LIMIT_MAX = 15      # max AI queries per minute


class ConnectionRateLimiter:
    """Per-connection rate limiter for WebSocket messages."""

    def __init__(self):
        self.general_timestamps = []
        self.ai_timestamps = []

    def check_general(self) -> bool:
        """Check if general message rate is exceeded. Returns True if allowed."""
        now = datetime.datetime.now()
        cutoff = now - datetime.timedelta(seconds=MSG_RATE_LIMIT_WINDOW)
        self.general_timestamps = [t for t in self.general_timestamps if t > cutoff]
        if len(self.general_timestamps) >= MSG_RATE_LIMIT_MAX:
            return False
        self.general_timestamps.append(now)
        return True

    def check_ai(self) -> bool:
        """Check if AI query rate is exceeded. Returns True if allowed."""
        now = datetime.datetime.now()
        cutoff = now - datetime.timedelta(seconds=MSG_RATE_LIMIT_WINDOW)
        self.ai_timestamps = [t for t in self.ai_timestamps if t > cutoff]
        if len(self.ai_timestamps) >= AI_RATE_LIMIT_MAX:
            return False
        self.ai_timestamps.append(now)
        return True


def _store_token(token: str, profile: dict):
    """Store a token with expiry — in-memory AND schedule async Redis write."""
    ACTIVE_TOKENS[token] = {
        "profile": profile,
        "expires": datetime.datetime.now() + datetime.timedelta(hours=TOKEN_TTL_HOURS)
    }
    hw_id = profile.get("hardware_id", "?")[:16]
    print(f"[TOKEN] Stored {hw_id} (memory + Redis scheduled)", flush=True)
    try:
        loop = asyncio.get_event_loop()
        if loop.is_running():
            loop.create_task(_store_token_redis(token, profile))
    except Exception:
        pass
    _prune_expired_tokens()

async def _store_token_redis(token: str, profile: dict):
    """Write token to Redis for cross-container auth (bridge → backend)."""
    global _token_redis_sync
    if _token_redis_sync is None and not _token_redis_init_done:
        await _init_token_redis_async()
    if _token_redis_sync:
        try:
            key = _redis_token_key(token)
            _token_redis_sync.setex(
                key,
                _TOKEN_REDIS_TTL_SECONDS,
                json.dumps(profile, default=str),
            )
        except Exception as e:
            print(f"[TOKEN] Redis write failed: {e}", flush=True)

def _revoke_token(token: str):
    """Atomically revoke a token from both in-memory and Redis."""
    entry = ACTIVE_TOKENS.pop(token, None)
    hw_id = "?"
    if entry and entry.get("profile"):
        hw_id = entry["profile"].get("hardware_id", "?")[:16]
    if _token_redis_sync:
        try:
            _token_redis_sync.delete(_redis_token_key(token))
        except Exception:
            pass
    print(f"[TOKEN] Revoked for {hw_id}", flush=True)

async def _revoke_all_tokens():
    """Emergency revocation: clear ALL tokens from memory and Redis (SCAN + DEL)."""
    count = len(ACTIVE_TOKENS)
    ACTIVE_TOKENS.clear()
    redis_count = 0
    if _token_redis_sync:
        try:
            prefix = f"{_REDIS_CONFIG['key_prefix']}:{_REDIS_CONFIG['env']}:auth:*"
            cursor = 0
            while True:
                cursor, keys = _token_redis_sync.scan(cursor=cursor, match=prefix, count=100)
                if keys:
                    _token_redis_sync.delete(*keys)
                    redis_count += len(keys)
                if cursor == 0:
                    break
        except Exception as e:
            print(f"[TOKEN] Emergency Redis revocation error: {e}", flush=True)
    print(f"[TOKEN] Emergency revocation: {count} memory + {redis_count} Redis tokens cleared", flush=True)

def _get_token_profile(token: str):
    """Get profile for token if valid and not expired (in-memory only)."""
    entry = ACTIVE_TOKENS.get(token)
    if not entry:
        return None
    if datetime.datetime.now() > entry["expires"]:
        del ACTIVE_TOKENS[token]
        hw_id = entry.get("profile", {}).get("hardware_id", "?")[:16]
        print(f"[TOKEN] Expired for {hw_id}", flush=True)
        return None
    return entry["profile"]


async def _get_token_profile_async(token: str):
    """Get profile for token — checks in-memory first, falls back to Redis.

    After a container restart ACTIVE_TOKENS is empty but Redis still has the
    token. This function recovers the session transparently and re-populates
    the in-memory cache so subsequent lookups are instant.
    """
    profile = _get_token_profile(token)
    if profile:
        return profile

    global _token_redis_sync
    if _token_redis_sync is None and not _token_redis_init_done:
        try:
            await _init_token_redis_async()
        except Exception:
            pass

    if _token_redis_sync:
        try:
            raw = _token_redis_sync.get(_redis_token_key(token))
            if raw:
                profile = json.loads(raw)
                ACTIVE_TOKENS[token] = {
                    "profile": profile,
                    "expires": datetime.datetime.now() + datetime.timedelta(hours=TOKEN_TTL_HOURS),
                }
                print(f"[TOKEN] Recovered from Redis for hw_id={profile.get('hardware_id', '?')[:16]}", flush=True)
                return profile
            else:
                print(f"[TOKEN] Redis miss for token={token[:8]}...", flush=True)
        except Exception as e:
            print(f"[TOKEN] Redis fallback error: {e}", flush=True)

    return None


def _prune_expired_tokens():
    """Remove expired tokens. Called on each new token store."""
    now = datetime.datetime.now()
    expired = [t for t, e in ACTIVE_TOKENS.items() if now > e["expires"]]
    for t in expired:
        hw_id = ACTIVE_TOKENS[t].get("profile", {}).get("hardware_id", "?")[:16]
        print(f"[TOKEN] Expired for {hw_id}", flush=True)
        del ACTIVE_TOKENS[t]

