def _is_coach_external_consultation_session(sess: dict) -> bool:
    """True for coach-scheduled external consultee sessions (non-roster)."""
    if not isinstance(sess, dict):
        return False
    st = str(sess.get("session_type") or "").strip().lower()
    if st == "consultation":
        return True
    if str(sess.get("booked_by") or "").strip() == "COACH_CONSULTATION":
        return True
    return str(sess.get("client_id") or "").startswith("consultation_")


async def _run_consultation_timer(
    session_id: str,
    master_hw_id: str,
    assistant_hw_id: str,
    duration_seconds: int = 900,
):
    """15-minute countdown for master-coach free consultations.

    Sends tick updates every 60s, warnings at 5-min and 1-min remaining,
    and auto-ends the session at expiry.
    """
    try:
        elapsed = 0
        while elapsed < duration_seconds:
            await asyncio.sleep(60)
            elapsed += 60
            remaining = max(0, duration_seconds - elapsed)
            remaining_min = remaining // 60

            payload = json.dumps({
                "type": "consultation_timer_update",
                "session_id": session_id,
                "remaining_seconds": remaining,
                "remaining_minutes": remaining_min,
                "elapsed_seconds": elapsed,
            })

            for hw_id in (master_hw_id, assistant_hw_id):
                ws = connected_coaches.get(hw_id) or connected_clients.get(hw_id)
                if ws:
                    try:
                        await ws.send(payload)
                    except Exception:
                        pass

            if remaining == 300:
                warning = json.dumps({
                    "type": "consultation_warning",
                    "session_id": session_id,
                    "minutes_left": 5,
                    "message": "5 minutes remaining in your consultation",
                })
                for hw_id in (master_hw_id, assistant_hw_id):
                    ws = connected_coaches.get(hw_id) or connected_clients.get(hw_id)
                    if ws:
                        try:
                            await ws.send(warning)
                        except Exception:
                            pass

            elif remaining == 60:
                warning = json.dumps({
                    "type": "consultation_warning",
                    "session_id": session_id,
                    "minutes_left": 1,
                    "message": "1 minute remaining — consultation will auto-close",
                })
                for hw_id in (master_hw_id, assistant_hw_id):
                    ws = connected_coaches.get(hw_id) or connected_clients.get(hw_id)
                    if ws:
                        try:
                            await ws.send(warning)
                        except Exception:
                            pass

        ended = json.dumps({
            "type": "consultation_ended",
            "session_id": session_id,
            "message": "Free consultation has ended. Thank you!",
        })
        for hw_id in (master_hw_id, assistant_hw_id):
            ws = connected_coaches.get(hw_id) or connected_clients.get(hw_id)
            if ws:
                try:
                    await ws.send(ended)
                except Exception:
                    pass

        if db_pool:
            try:
                await db_pool.execute(
                    """UPDATE coaching_sessions SET status = 'completed',
                              actual_end = NOW(), duration_minutes = $1,
                              updated_at = NOW()
                       WHERE session_id = $2 AND status != 'completed'""",
                    duration_seconds // 60, session_id,
                )
                await db_pool.execute(
                    """INSERT INTO supervised_hours
                              (master_coach_id, assistant_id, activity_type,
                               duration_minutes, attestation_status, created_at)
                       VALUES ($1, $2, 'consultation', $3, 'auto_logged', NOW())""",
                    master_hw_id, assistant_hw_id, duration_seconds // 60,
                )
            except Exception as _e:
                print(f">>> [CONSULTATION] DB finalize failed: {_e}")

    except asyncio.CancelledError:
        pass
    finally:
        _consultation_timers.pop(session_id, None)


async def _flush_activity_cache():
    """Flush _activity_cache to PostgreSQL every 5 minutes."""
    while True:
        await asyncio.sleep(300)
        if not _activity_cache or not db_pool:
            continue
        batch = dict(_activity_cache)
        _activity_cache.clear()
        try:
            async with db_pool.acquire() as conn:
                for hw_id, ts in batch.items():
                    await conn.execute(
                        """UPDATE users SET profile_data = jsonb_set(
                            COALESCE(profile_data, '{}'::jsonb),
                            '{last_activity_at}', to_jsonb($1::text)
                        ) WHERE hardware_id = $2""",
                        ts, hw_id,
                    )
        except Exception as e:
            print(f">>> [ACTIVITY CACHE] Flush failed: {e}")


async def _ws_stale_cleanup_loop():
    """Periodic sweep to remove stale WebSocket entries from connection dicts.

    Runs every 60 seconds. Checks if each stored websocket is still open;
    removes entries whose underlying transport has closed.
    """
    while True:
        await asyncio.sleep(60)
        for label, conn_dict in [("coach", connected_coaches), ("client", connected_clients)]:
            stale_ids = []
            for uid, ws in list(conn_dict.items()):
                try:
                    if ws.closed:
                        stale_ids.append(uid)
                except Exception:
                    stale_ids.append(uid)
            for uid in stale_ids:
                conn_dict.pop(uid, None)
            if stale_ids:
                print(f"[Heartbeat] Removed {len(stale_ids)} stale {label} connection(s)")


def _replace_connection(uid: str, new_ws, conn_dict: Dict[str, Any]):
    """Register a new websocket, closing the old one if it exists and is stale."""
    old_ws = conn_dict.get(uid)
    if old_ws is not None and old_ws is not new_ws:
        try:
            if not old_ws.closed:
                asyncio.create_task(old_ws.close(1000, "Replaced by new connection"))
        except Exception:
            pass
    conn_dict[uid] = new_ws

async def send_coach_notification(coach_id: str, message_type: str, data: Dict):
    """
    Send a WebSocket notification to a connected coach.
    Called by classroom_analyzer when AI analysis completes.
    """
    ws = connected_coaches.get(coach_id)
    if ws:
        try:
            await ws.send(json.dumps({
                "type": message_type,
                **data
            }))
            print(f"[Notification] Sent {message_type} to coach {coach_id}")
        except Exception as e:
            print(f"[Notification] Error sending to {coach_id}: {e}")
            # Remove stale connection
            connected_coaches.pop(coach_id, None)
    else:
        print(f"[Notification] Coach {coach_id} not connected, notification queued")

