# PART 7: BILLING & SUBSCRIPTION SYSTEM
# ------------------------------------------------------------------------------
class BillingSystem:
    PLAN_DETAILS = {
        "COACH_ONLY": {"tokens": 0, "price": 0, "duration_days": 365, "can_access_nate": False},
        "TRIAL": {"tokens": 10000, "price": 0, "duration_days": 7},
        "STANDARD": {"tokens": 50000, "price": 49, "duration_days": 30},
        "TOP_TIER": {"tokens": 200000, "price": 149, "duration_days": 30},
    }

    def __init__(self, data_dir: Path):
        self.billing_file = data_dir / "billing.json"
        self.transactions_file = data_dir / "transactions.json"
        self.db_pool = None

    def load_billing(self) -> dict:
        return load_json_file(self.billing_file, {"customers": {}, "subscriptions": {}})

    def save_billing(self, data: dict) -> bool:
        return save_json_file(self.billing_file, data)

    def create_customer(self, user_id: str, email: str, name: str) -> dict:
        """Create billing customer record in PG (profile_data), JSON as backup."""
        customer = {
            "user_id": user_id,
            "email": email,
            "name": name,
            "stripe_customer_id": "",
            "created_at": str(datetime.datetime.now()),
            "payment_methods": [],
            "default_payment_method": ""
        }
        billing = self.load_billing()
        billing["customers"][user_id] = customer
        self.save_billing(billing)
        return customer

    def create_subscription(self, user_id: str, plan: str,
                           price_id: str = "", stripe_sub_id: str = "") -> dict:
        """Create subscription. Writes to PG users table + JSON backup."""
        details = self.PLAN_DETAILS.get(plan, self.PLAN_DETAILS["STANDARD"])

        subscription = {
            "user_id": user_id,
            "plan": plan,
            "stripe_subscription_id": stripe_sub_id,
            "stripe_price_id": price_id,
            "status": "active",
            "tokens_included": details["tokens"],
            "monthly_price": details["price"],
            "start_date": str(datetime.datetime.now().date()),
            "end_date": str((datetime.datetime.now() + datetime.timedelta(days=details["duration_days"])).date()),
            "next_billing_date": str((datetime.datetime.now() + datetime.timedelta(days=details["duration_days"])).date()),
            "created_at": str(datetime.datetime.now()),
            "cancelled_at": None
        }

        if self.db_pool:
            try:
                loop = asyncio.get_running_loop()
                loop.create_task(self._pg_create_subscription(
                    user_id, plan, details["tokens"], subscription
                ))
            except RuntimeError:
                pass

        registry = load_registry()
        for k, v in registry.items():
            if v["profile"].get("hardware_id") == user_id:
                v["profile"]["subscription_plan"] = plan
                v["profile"]["subscription_status"] = "ACTIVE"
                v["profile"]["token_balance"] = details["tokens"]
                save_registry(registry, changed_keys=[k])
                break

        billing = self.load_billing()
        billing["subscriptions"][user_id] = subscription
        self.save_billing(billing)
        return subscription

    async def _pg_create_subscription(self, user_id: str, plan: str, tokens: int, sub_data: dict):
        """Write subscription to PG and update the users table atomically."""
        try:
            async with self.db_pool.acquire() as conn:
                await conn.execute("""
                    UPDATE users SET
                        subscription_status = 'ACTIVE',
                        tier = $1,
                        token_balance = $2,
                        profile_data = jsonb_set(
                            jsonb_set(
                                jsonb_set(
                                    COALESCE(profile_data, '{}'::jsonb),
                                    '{subscription_plan}', to_jsonb($1::text)
                                ),
                                '{subscription_status}', '"ACTIVE"'::jsonb
                            ),
                            '{token_balance}', to_jsonb($2::int)
                        )
                    WHERE hardware_id = $3
                """, plan, tokens, user_id)
        except Exception as e:
            print(f">>> [BILLING] PG subscription create failed: {e}")

    def get_subscription(self, user_id: str) -> Optional[dict]:
        """Get user's subscription — PG first, JSON fallback."""
        if self.db_pool:
            try:
                loop = asyncio.get_running_loop()
                future = asyncio.run_coroutine_threadsafe(
                    self._pg_get_subscription(user_id), loop
                )
                result = future.result(timeout=2)
                if result:
                    return result
            except Exception:
                pass
        billing = self.load_billing()
        return billing.get("subscriptions", {}).get(user_id)

    async def _pg_get_subscription(self, user_id: str) -> Optional[dict]:
        """Read subscription from PG users table (profile_data)."""
        try:
            async with self.db_pool.acquire() as conn:
                row = await conn.fetchrow("""
                    SELECT subscription_status, tier,
                           COALESCE(token_balance, 0) as token_balance,
                           profile_data->>'subscription_plan' as plan
                    FROM users WHERE hardware_id = $1
                """, user_id)
                if row:
                    plan = row["plan"] or row["tier"] or "TRIAL"
                    details = self.PLAN_DETAILS.get(plan, self.PLAN_DETAILS["STANDARD"])
                    return {
                        "user_id": user_id,
                        "plan": plan,
                        "status": (row["subscription_status"] or "ACTIVE").lower(),
                        "tokens_included": details["tokens"],
                        "monthly_price": details["price"],
                    }
        except Exception as e:
            print(f">>> [BILLING] PG get_subscription failed: {e}")
        return None
    
    def record_transaction(
        self,
        user_id: str,
        amount: float,
        description: str,
        transaction_type: str = "charge",
        status: str = "completed",
        metadata: dict = None,
    ) -> dict:
        """Record a billing transaction"""
        transactions = load_json_file(self.transactions_file, [])
        
        transaction = {
            "transaction_id": f"TXN_{secrets.token_hex(8).upper()}",
            "user_id": user_id,
            "amount": amount,
            "currency": "USD",
            "description": description,
            "type": transaction_type,  # charge, refund, credit
            "status": status,
            "created_at": str(datetime.datetime.now()),
            "metadata": metadata or {},
        }
        
        transactions.append(transaction)
        save_json_file(self.transactions_file, transactions)
        
        return transaction
    
    def use_tokens(self, user_id: str, tokens_used: int, source: str = None) -> Tuple[bool, int]:
        """Deduct tokens from user's balance. Purchased bucket first, then subscription."""
        # SOVEREIGN-VOICE: subscription/purchased token bucket split (Phase 2, migration 194).
        from app.services.token_balance_policy import (
            apply_deduction,
            split_balances_from_profile,
            total_balance,
        )

        registry = load_registry()

        for k, v in registry.items():
            profile = v.get("profile", {})
            if profile.get("hardware_id") == user_id:
                sub, purch = split_balances_from_profile(profile)
                current_balance = total_balance(sub, purch)

                if current_balance < tokens_used:
                    return False, current_balance

                new_sub, new_purch = apply_deduction(sub, purch, tokens_used)
                new_total = total_balance(new_sub, new_purch)
                profile["subscription_token_balance"] = new_sub
                profile["purchased_token_balance"] = new_purch
                profile["token_balance"] = new_total
                profile["token_usage_today"] = profile.get("token_usage_today", 0) + tokens_used
                profile["token_usage_month"] = profile.get("token_usage_month", 0) + tokens_used

                save_registry(registry, changed_keys=[k])

                username = profile.get("username", k)
                if source:
                    self._log_token_transaction(
                        username,
                        "deduct",
                        -tokens_used,
                        current_balance,
                        new_total,
                        source,
                        sub_before=sub,
                        sub_after=new_sub,
                    )

                if hasattr(self, "db_pool") and self.db_pool:
                    try:
                        import asyncio

                        loop = asyncio.get_event_loop()
                        if loop.is_running():
                            loop.create_task(self._atomic_deduct(username, tokens_used))
                            loop.create_task(self._report_meter_usage(username, tokens_used, source))
                    except Exception:
                        pass

                return True, new_total

        return False, 0

    async def _report_meter_usage(self, username: str, tokens: int, source: str = None):
        """Fire-and-forget: report token usage to Stripe Meter."""
        try:
            from app.services.stripe_integration import report_token_usage_by_username
            await report_token_usage_by_username(self.db_pool, username, tokens, source or "ai_chat")
        except Exception as e:
            _logger = logging.getLogger("bridge")
            _logger.debug("Stripe meter report skipped for %s: %s", username, e)

    async def _atomic_deduct(self, username: str, amount: int):
        """Atomic deduction: purchased bucket first, then subscription; token_balance = sum."""
        # SOVEREIGN-VOICE: bucket-aware atomic deduction (Phase 2, migration 194).
        # SOVEREIGN-VOICE: reconcile token_balance − (sub+purch) into subscription before deduct
        # when bucket columns are stale zero (Token Lab / grants bump token_balance only).
        try:
            async with self.db_pool.acquire() as conn:
                await conn.execute(
                    """
                    UPDATE users SET
                      purchased_token_balance = GREATEST(
                          0,
                          COALESCE(purchased_token_balance, 0)
                          - LEAST(COALESCE(purchased_token_balance, 0), $1)
                      ),
                      subscription_token_balance = GREATEST(
                          0,
                          (
                              COALESCE(subscription_token_balance, 0)
                              + GREATEST(
                                  0,
                                  COALESCE(token_balance, 0)
                                  - COALESCE(subscription_token_balance, 0)
                                  - COALESCE(purchased_token_balance, 0)
                              )
                          )
                          - GREATEST(
                              0,
                              $1 - LEAST(COALESCE(purchased_token_balance, 0), $1)
                          )
                      ),
                      token_balance =
                          GREATEST(
                              0,
                              (
                                  COALESCE(subscription_token_balance, 0)
                                  + GREATEST(
                                      0,
                                      COALESCE(token_balance, 0)
                                      - COALESCE(subscription_token_balance, 0)
                                      - COALESCE(purchased_token_balance, 0)
                                  )
                              )
                              - GREATEST(
                                  0,
                                  $1 - LEAST(COALESCE(purchased_token_balance, 0), $1)
                              )
                          )
                        + GREATEST(
                              0,
                              COALESCE(purchased_token_balance, 0)
                              - LEAST(COALESCE(purchased_token_balance, 0), $1)
                          )
                    WHERE username = $2 AND COALESCE(token_balance, 0) >= $1
                    """,
                    amount,
                    username,
                )
        except Exception as e:
            _logger = logging.getLogger("bridge")
            _logger.warning("Atomic token deduct failed for %s: %s", username, e)

    def add_token_usage(self, user_id: str, tokens_used: int, deduct_balance: bool = False, source: str = None) -> Tuple[bool, int]:
        """
        Record token usage on a profile.

        - Always increments token_usage_today/month.
        - Optionally decrements token_balance when deduct_balance=True.
        - source tags the consumption point (ai_chat, sanctuary_ai, etc.)
        Returns (success, resulting_balance).

        # SOVEREIGN-VOICE: bucket-aware usage + optional deduction (Phase 2, migration 194).
        """
        from app.services.token_balance_policy import (
            apply_deduction,
            split_balances_from_profile,
            total_balance,
        )

        try:
            tokens_used = int(tokens_used or 0)
        except Exception:
            tokens_used = 0

        if tokens_used <= 0:
            registry = load_registry()
            for _, v in (registry or {}).items():
                p = (v or {}).get("profile", {}) or {}
                if p.get("hardware_id") == user_id:
                    sub, purch = split_balances_from_profile(p)
                    return True, total_balance(sub, purch)
            return True, 0

        registry = load_registry()
        matched_key = None
        for rk, v in (registry or {}).items():
            profile = (v or {}).get("profile", {}) or {}
            if profile.get("hardware_id") != user_id:
                continue
            matched_key = rk

            sub, purch = split_balances_from_profile(profile)
            current_balance = total_balance(sub, purch)

            if deduct_balance:
                if current_balance < tokens_used:
                    return False, current_balance
                new_sub, new_purch = apply_deduction(sub, purch, tokens_used)
                new_total = total_balance(new_sub, new_purch)
                profile["subscription_token_balance"] = new_sub
                profile["purchased_token_balance"] = new_purch
                profile["token_balance"] = new_total
                sub_before, sub_after = sub, new_sub
            else:
                new_total = current_balance
                sub_before = sub_after = None

            profile["token_usage_today"] = int(profile.get("token_usage_today", 0) or 0) + tokens_used
            profile["token_usage_month"] = int(profile.get("token_usage_month", 0) or 0) + tokens_used
            save_registry(registry, changed_keys=[matched_key] if matched_key else None)

            if source and hasattr(self, "_log_token_transaction"):
                try:
                    amt = -tokens_used if deduct_balance else tokens_used
                    self._log_token_transaction(
                        profile.get("username", ""),
                        "usage",
                        amt,
                        current_balance,
                        new_total,
                        source,
                        sub_before=sub_before if deduct_balance else None,
                        sub_after=sub_after if deduct_balance else None,
                    )
                except Exception:
                    pass

            if hasattr(self, "db_pool") and self.db_pool and source:
                try:
                    import asyncio

                    loop = asyncio.get_event_loop()
                    if loop.is_running():
                        loop.create_task(self._report_meter_usage(profile.get("username", ""), tokens_used, source))
                        if deduct_balance:
                            loop.create_task(self._atomic_deduct(profile.get("username", ""), tokens_used))
                except Exception:
                    pass

            return True, int(new_total)

        return False, 0

    # SOVEREIGN-VOICE: subscription bucket fields added (Phase 2, migration 194).
    def _log_token_transaction(
        self,
        username,
        action,
        amount,
        before,
        after,
        source=None,
        sub_before=None,
        sub_after=None,
    ):
        """Fire-and-forget async logging of token transaction to PostgreSQL."""
        try:
            import asyncio

            loop = asyncio.get_event_loop()
            if loop.is_running():
                loop.create_task(
                    self._async_log_token_tx(
                        username, action, amount, before, after, source, sub_before, sub_after
                    )
                )
        except Exception as e:
            logging.getLogger("bridge").warning("Token tx log dispatch failed: %s", e)

    # SOVEREIGN-VOICE: writes subscription_balance_before/after columns (Phase 2, migration 194).
    async def _async_log_token_tx(
        self,
        username,
        action,
        amount,
        before,
        after,
        source,
        sub_before=None,
        sub_after=None,
    ):
        """Write token transaction row to PostgreSQL with 1 retry."""
        if not hasattr(self, "db_pool") or not self.db_pool:
            return
        import re

        clean_username = re.sub(r"^(client_|coach_|admin_)", "", username)
        for attempt in range(2):
            try:
                async with self.db_pool.acquire() as conn:
                    await conn.execute(
                        """
                        INSERT INTO token_transactions
                            (username, action, amount, balance_before, balance_after,
                             source, initiated_by, target_scope,
                             subscription_balance_before, subscription_balance_after)
                        VALUES ($1, $2, $3, $4, $5, $6, 'system', 'individual', $7, $8)
                    """,
                        clean_username,
                        action,
                        amount,
                        before,
                        after,
                        source,
                        sub_before,
                        sub_after,
                    )
                return
            except Exception as e:
                if attempt == 0:
                    import asyncio
                    await asyncio.sleep(0.5)
                else:
                    logging.getLogger("bridge").warning(
                        "Token tx log failed after retry for %s: %s", username, e
                    )

    def get_usage_stats(self, user_id: str) -> dict:
        """Get token usage statistics"""
        registry = load_registry()
        
        for k, v in registry.items():
            profile = v.get("profile", {})
            if profile.get("hardware_id") == user_id:
                return {
                    "token_balance": profile.get("token_balance", 0),
                    "tokens_used_today": profile.get("token_usage_today", 0),
                    "tokens_used_month": profile.get("token_usage_month", 0),
                    "subscription_plan": profile.get("subscription_plan", "TRIAL"),
                    "subscription_status": profile.get("subscription_status", "TRIAL_ACTIVE")
                }
        
        return {}

# ------------------------------------------------------------------------------
# PART 8: NIGHT SCHOOL (Learning Engine)
# ------------------------------------------------------------------------------
class NightSchool:
    def __init__(self, root: Path):
        self.root = root
        self.wisdom_file = root / "Admin" / "little_nate_wisdom.json"
        self.learnings_file = root / "Admin" / "learning_history.json"
        self.db_pool = None  # set when bridge creates asyncpg pool
    
    def load_wisdom(self) -> str:
        if not self.wisdom_file.exists():
            return "Focus on empathy, safety, and client growth. Always validate feelings before offering solutions."
        try:
            with open(self.wisdom_file, 'r') as f:
                data = json.load(f)
                return data.get("accumulated_learnings", "Focus on empathy and safety.")
        except:
            return "Focus on empathy and safety."
    
    def get_wisdom_structured(self) -> dict:
        """Get structured wisdom data"""
        if not self.wisdom_file.exists():
            return {"accumulated_learnings": "", "entries": [], "last_synthesis": ""}
        try:
            with open(self.wisdom_file, 'r') as f:
                return json.load(f)
        except:
            return {"accumulated_learnings": "", "entries": [], "last_synthesis": ""}

    async def start_session(self):
        """Run Night School learning session"""
        print("[*] NIGHT SCHOOL: Session Active. Scanning training materials...")
        
        # Process Admin folder
        admin_folder = self.root / "Admin" / "admin_LN_training_folder"
        if admin_folder.exists():
            await self._process_folder(admin_folder, "ADMIN_CURRICULUM")
        
        # Process Coach folders
        coaches_dir = self.root / "Coaches"
        if coaches_dir.exists():
            for coach_dir in coaches_dir.iterdir():
                if coach_dir.is_dir():
                    for sub in coach_dir.iterdir():
                        if sub.is_dir() and sub.name.endswith("_LN_training_folder"):
                            await self._process_folder(sub, f"COACH_{coach_dir.name}")
        
        # Synthesize learnings
        await self._synthesize_learnings()
        
        print("[*] NIGHT SCHOOL: Session Complete.")

    async def _process_folder(self, folder_path: Path, source_tag: str):
        """Process training materials from a folder"""
        if not folder_path.exists():
            return
        
        for file in folder_path.iterdir():
            if file.suffix in ['.txt', '.log', '.json', '.md']:
                try:
                    with open(file, 'r', encoding='utf-8') as f:
                        content = f.read()
                        if len(content) > 10:
                            print(f"   [NIGHT SCHOOL] Ingesting {file.name} from {source_tag}...")
                            self.add_learning(
                                content=content[:2000],
                                source=source_tag,
                                filename=file.name
                            )
                except Exception as e:
                    print(f"   [NIGHT SCHOOL] Error reading {file.name}: {e}")

    def add_learning(self, content: str, source: str, filename: str = "", 
                    category: str = "general"):
        """Append a raw learning to learning_history.json (deduped). Merged into
        little_nate_wisdom.json + night_school_wisdom (PG) by _synthesize_learnings."""
        learnings = load_json_file(self.learnings_file, [])
        if not isinstance(learnings, list):
            learnings = []

        # Check for duplicates
        content_hash = hashlib.md5(content.encode()).hexdigest()
        for entry in learnings:
            if entry.get("content_hash") == content_hash:
                return  # Skip duplicate

        entry = {
            "id": secrets.token_hex(8),
            "content": content,
            "content_hash": content_hash,
            "source": source,
            "filename": filename,
            "category": category,
            "timestamp": str(datetime.datetime.now()),
            "times_applied": 0,
            "effectiveness_score": 0.5,
            "deprecated": False
        }

        learnings.append(entry)
        save_json_file(self.learnings_file, learnings[-1000:])  # Keep last 1000

    async def _synthesize_learnings(self):
        """Merge ingestion learnings into little_nate_wisdom.json (append-only; editor CRUD entries preserved)."""
        learnings = load_json_file(self.learnings_file, [])
        if not isinstance(learnings, list) or not learnings:
            return

        active_learnings = [l for l in learnings if not l.get("deprecated", False)]
        recent = active_learnings[-50:]

        # Load existing wisdom from disk (same paths as editor CRUD) — never replace whole file blindly.
        existing = self.get_wisdom_structured()
        if not isinstance(existing, dict):
            existing = {"accumulated_learnings": "", "entries": [], "last_synthesis": ""}
        entries = existing.get("entries")
        if not isinstance(entries, list):
            entries = []

        merged_learning_ids = set()
        for e in entries:
            if isinstance(e, dict) and e.get("ingestion_learning_id"):
                merged_learning_ids.add(e["ingestion_learning_id"])

        max_entry_id = 0
        for e in entries:
            if isinstance(e, dict):
                try:
                    max_entry_id = max(max_entry_id, int(e.get("id", 0)))
                except (TypeError, ValueError):
                    pass

        new_rows_pg: List[Tuple[str, str, str, str, float]] = []
        added_any = False

        for l in recent:
            lid = l.get("id")
            if not lid or lid in merged_learning_ids:
                continue
            max_entry_id += 1
            raw_content = (l.get("content") or "")[:2000]
            src = str(l.get("source", "night_school"))[:200]
            cat = (l.get("category", "general") or "general")[:128]
            conf = float(l.get("effectiveness_score", 0.5) or 0.5)
            ent = {
                "id": max_entry_id,
                "category": cat,
                "source": src,
                "content": raw_content,
                "confidence": conf,
                "approved": True,
                "timestamp": l.get("timestamp") or str(datetime.datetime.now()),
                "ingestion_learning_id": lid,
            }
            entries.append(ent)
            merged_learning_ids.add(lid)
            added_any = True
            new_rows_pg.append((f"ns_{lid}", cat, raw_content, src, conf))

        if not added_any:
            return

        categories: Dict[str, List[str]] = {}
        for l in recent:
            cat = l.get("category", "general")
            if cat not in categories:
                categories[cat] = []
            categories[cat].append((l.get("content") or "")[:200])

        synthesis_parts = []
        for cat, contents in categories.items():
            synthesis_parts.append(f"[{str(cat).upper()}]: {'; '.join(contents[:5])}")

        synth_block = "\n".join(synthesis_parts)
        ts = str(datetime.datetime.now())

        if synth_block:
            old_acc = (existing.get("accumulated_learnings") or "").strip()
            marker = f"\n\n--- Night School synthesis {ts} ---\n"
            existing["accumulated_learnings"] = (old_acc + marker + synth_block).strip()

        existing["entries"] = entries
        existing["last_synthesis"] = ts
        existing["entries_count"] = len(entries)
        cat_list = existing.get("categories")
        if not isinstance(cat_list, list):
            cat_list = []
        for c in categories.keys():
            if c not in cat_list:
                cat_list.append(c)
        existing["categories"] = cat_list

        save_json_file(self.wisdom_file, existing)

        pool = getattr(self, "db_pool", None)
        if pool and new_rows_pg:
            try:
                async with pool.acquire() as conn:
                    await conn.execute(
                        """
                        CREATE TABLE IF NOT EXISTS night_school_wisdom (
                            id SERIAL PRIMARY KEY,
                            entry_id VARCHAR UNIQUE,
                            category VARCHAR,
                            content TEXT,
                            source_tag VARCHAR,
                            confidence FLOAT DEFAULT 0.5,
                            created_at TIMESTAMPTZ DEFAULT NOW()
                        )
                        """
                    )
                    for entry_id, cat, content, source_tag, confidence in new_rows_pg:
                        await conn.execute(
                            """
                            INSERT INTO night_school_wisdom (entry_id, category, content, source_tag, confidence)
                            VALUES ($1, $2, $3, $4, $5)
                            ON CONFLICT (entry_id) DO NOTHING
                            """,
                            entry_id,
                            cat,
                            content,
                            source_tag,
                            confidence,
                        )
            except Exception as pg_err:
                print(f">>> [NIGHT SCHOOL] night_school_wisdom PG write failed (non-fatal): {pg_err}")

    def get_coach_contribution(self, coach_id: str) -> dict:
        """Get learning contributions from a specific coach"""
        learnings = load_json_file(self.learnings_file, [])
        coach_learnings = [l for l in learnings if coach_id in l.get("source", "")]
        
        return {
            "total_contributions": len(coach_learnings),
            "categories": list(set(l.get("category", "general") for l in coach_learnings)),
            "recent": coach_learnings[-10:]
        }

# ------------------------------------------------------------------------------
# PART 9: ANALYTICS ENGINE
# ------------------------------------------------------------------------------
class AnalyticsEngine:
    def __init__(self, data_dir: Path):
        self.analytics_file = data_dir / "analytics.json"
    
    def load_analytics(self) -> dict:
        default = {
            "schema_version": 2,
            "daily_stats": {},
            "platform_totals": {
                "total_users": 0,
                "total_sessions": 0,
                "total_messages": 0,
                "total_tokens_used": 0,
            },
            # Append-only event stream used by dashboards / flow-tree charts.
            # (Keep bounded via retention trimming in record_event.)
            "events": [],
        }
        analytics = load_json_file(self.analytics_file, default)
        if not isinstance(analytics, dict):
            analytics = dict(default)

        # Backward-compat: ensure required keys exist
        analytics.setdefault("schema_version", 2)
        analytics.setdefault("daily_stats", {})
        analytics.setdefault("platform_totals", {})
        analytics.setdefault("events", [])

        pt = analytics.get("platform_totals")
        if not isinstance(pt, dict):
            pt = {}
            analytics["platform_totals"] = pt
        pt.setdefault("total_users", 0)
        pt.setdefault("total_sessions", 0)
        pt.setdefault("total_messages", 0)
        pt.setdefault("total_tokens_used", 0)

        if not isinstance(analytics.get("events"), list):
            analytics["events"] = []

        return analytics
    
    def save_analytics(self, data: dict) -> bool:
        return save_json_file(self.analytics_file, data)
    
    def record_event(self, event_type: str, user_id: str = None, data: dict = None):
        """Record an analytics event"""
        analytics = self.load_analytics()
        today = str(datetime.datetime.now().date())
        
        if today not in analytics["daily_stats"]:
            analytics["daily_stats"][today] = {
                "logins": 0,
                "registrations": 0,
                "messages_sent": 0,
                "tokens_used": 0,
                "sessions_started": 0,
                "active_users": []
            }
        
        day_stats = analytics["daily_stats"][today]

        # Normalize active_users
        if not isinstance(day_stats.get("active_users"), list):
            day_stats["active_users"] = []

        # Persist append-only event stream for dashboards / flow-tree
        try:
            event = {
                "event_id": f"EVT_{secrets.token_hex(6).upper()}",
                "timestamp": str(datetime.datetime.now()),
                "event_type": event_type,
                "user_id": user_id,
                "data": (data if isinstance(data, dict) else {}),
            }
            analytics.setdefault("events", [])
            if isinstance(analytics["events"], list):
                analytics["events"].append(event)
                # Retention: keep last N events (default 5000)
                try:
                    keep = int(os.getenv("ANALYTICS_EVENT_RETENTION", "5000") or 5000)
                except Exception:
                    keep = 5000
                if keep > 0 and len(analytics["events"]) > keep:
                    analytics["events"] = analytics["events"][-keep:]
        except Exception as e:
            print(f">>> [ANALYTICS] Event append failed: {e}")

        # Aggregate counters (best-effort)
        et = (event_type or "").strip()
        et_lower = et.lower()

        if et in ("login", "auth_success", "login_success"):
            day_stats["logins"] = day_stats.get("logins", 0) + 1
            if user_id and user_id not in day_stats.get("active_users", []):
                day_stats["active_users"].append(user_id)
        elif event_type == "registration":
            day_stats["registrations"] = day_stats.get("registrations", 0) + 1
            analytics["platform_totals"]["total_users"] += 1
        elif et in ("message",) or et_lower.startswith("sanctuary_message") or et_lower in ("sanctuary_ai_response", "sanctuary_coaching_message"):
            day_stats["messages_sent"] = day_stats.get("messages_sent", 0) + 1
            analytics["platform_totals"]["total_messages"] += 1
        elif event_type == "tokens":
            tokens = data.get("tokens", 0) if isinstance(data, dict) else 0
            day_stats["tokens_used"] = day_stats.get("tokens_used", 0) + tokens
            analytics["platform_totals"]["total_tokens_used"] += tokens
        else:
            # If any event includes token usage, count it
            try:
                if isinstance(data, dict) and data.get("tokens") is not None:
                    tokens = int(data.get("tokens") or 0)
                    day_stats["tokens_used"] = day_stats.get("tokens_used", 0) + tokens
                    analytics["platform_totals"]["total_tokens_used"] += tokens
            except Exception:
                pass

        if et in ("session_start", "sanctuary_session_started"):
            day_stats["sessions_started"] = day_stats.get("sessions_started", 0) + 1
            analytics["platform_totals"]["total_sessions"] += 1
        
        self.save_analytics(analytics)
    
    def get_dashboard_stats(self) -> dict:
        """Get stats for admin dashboard"""
        analytics = self.load_analytics()
        registry = load_registry()
        today = str(datetime.datetime.now().date())
        
        today_stats = analytics.get("daily_stats", {}).get(today, {})
        
        # Count users by role
        total_users = len(registry)
        coaches = sum(1 for v in registry.values() if v.get("profile", {}).get("role") == "COACH")
        clients = sum(1 for v in registry.values() if v.get("profile", {}).get("role") == "CLIENT")
        
        # Active users today
        active_users = today_stats.get("active_users", [])
        if isinstance(active_users, set):
            active_users = list(active_users)
        
        # Token usage rollups from registry (authoritative per-user counters)
        tokens_used_today = 0
        tokens_used_month = 0
        try:
            for v in (registry or {}).values():
                p = (v or {}).get("profile", {}) or {}
                tokens_used_today += int(p.get("token_usage_today", 0) or 0)
                tokens_used_month += int(p.get("token_usage_month", 0) or 0)
        except Exception:
            tokens_used_today = 0
            tokens_used_month = 0

        # Revenue rollup from transactions.json (includes test_mode entries)
        total_revenue = 0.0
        try:
            transactions_path = Path(self.analytics_file).parent / "transactions.json"
            txns = load_json_file(transactions_path, []) or []
            if isinstance(txns, list):
                for t in txns:
                    if not isinstance(t, dict):
                        continue
                    status = str(t.get("status") or "").lower()
                    if status not in ("completed", "test_mode"):
                        continue
                    try:
                        amt = float(t.get("amount", 0.0) or 0.0)
                    except Exception:
                        amt = 0.0
                    if amt > 0:
                        total_revenue += amt
        except Exception:
            total_revenue = 0.0

        # Count unresolved crisis entries for dashboard (historical from crisis_log)
        crisis_count = 0
        try:
            crisis_log = load_json_file(CRISIS_LOG_FILE, []) or []
            if isinstance(crisis_log, list):
                crisis_count = sum(1 for c in crisis_log if isinstance(c, dict) and c.get("status") != "resolved")
        except Exception:
            crisis_count = 0

        # Count live watchlist from current metrics (real-time risk scan)
        watchlist_count = 0
        try:
            watchlist_count = len(self.get_crisis_watchlist())
        except Exception:
            watchlist_count = 0

        # Count Zoom ingested sessions (Patent 2 Section 16)
        zoom_ingested_count = 0
        zoom_connected = False
        try:
            zoom_ingested_path = Path(self.analytics_file).parent / "zoom_ingested_sessions.json"
            zoom_data = load_json_file(zoom_ingested_path, []) or []
            if isinstance(zoom_data, list):
                zoom_ingested_count = sum(1 for z in zoom_data if isinstance(z, dict) and z.get("status") == "ingested")
                zoom_connected = len(zoom_data) > 0
        except Exception:
            zoom_ingested_count = 0

        # Count ACTIVE coach live sessions (real coaching, not WebSocket connections)
        active_coaching = 0
        try:
            live_store = load_json_file(COACH_LIVE_SESSIONS_FILE, {}) or {}
            active_coaching = sum(
                1 for s in live_store.values()
                if isinstance(s, dict) and s.get("status") == "ACTIVE"
            )
        except Exception:
            active_coaching = 0

        return {
            "active_users": len(active_users),
            "total_users": total_users,
            "coaches_count": coaches,
            "clients_count": clients,
            "live_sessions": active_coaching,
            # Sovereign Command dashboard aliases
            "active_sessions": active_coaching,
            "app_users_online": len(connected_clients),
            "total_coaches": coaches,
            "coaches_online": len(connected_coaches),
            "coaches_active_today": len(connected_coaches),
            "sessions_today": today_stats.get("sessions_started", 0),
            "crisis_count": crisis_count,
            "watchlist_count": watchlist_count,
            "today_logins": today_stats.get("logins", 0),
            "today_registrations": today_stats.get("registrations", 0),
            "today_messages": today_stats.get("messages_sent", 0),
            "today_tokens": today_stats.get("tokens_used", 0),
            # Back-compat fields used by The Eye dashboard pages
            "tokens_used_today": tokens_used_today,
            "tokens_used_month": tokens_used_month,
            "total_revenue": round(total_revenue, 2),
            "total_tokens_used": tokens_used_today + tokens_used_month,
            "total_sessions": analytics.get("platform_totals", {}).get("total_sessions", 0),
            "platform_totals": analytics.get("platform_totals", {}),
            "online_coach_ids": list(connected_coaches.keys()),
            "online_client_ids": list(connected_clients.keys()),
            "zoom_ingested_count": zoom_ingested_count,
            "zoom_connected": zoom_connected,
        }
    
    def get_crisis_watchlist(self) -> List[dict]:
        """Get users with elevated risk levels"""
        watchlist = []
        registry = load_registry()
        metrics_engine = MetricsEngine(VAULT_ROOT)
        
        for k, v in registry.items():
            profile = v.get("profile", {})
            if profile.get("role") != "CLIENT":
                continue
            
            metrics = metrics_engine.load_metrics(profile)
            ns = metrics.get("nevedal_state", {})
            
            risk = ns.get("risk_level", "LOW")
            if risk in ["MEDIUM", "HIGH", "CRITICAL"]:
                watchlist.append({
                    "user_id": profile.get("hardware_id"),
                    "name": profile.get("name"),
                    "risk_level": risk,
                    "anxiety_level": ns.get("anxiety_level", 0),
                    "depression_indicators": ns.get("depression_indicators", 0),
                    "last_assessment": ns.get("last_risk_assessment", ""),
                    "assigned_coach": profile.get("assigned_coach_id", "")
                })
        
        # Sort by risk level
        risk_order = {"CRITICAL": 0, "HIGH": 1, "MEDIUM": 2}
        watchlist.sort(key=lambda x: risk_order.get(x["risk_level"], 3))
        
        return watchlist


def _cohort_time_range_since(time_range: Optional[str]) -> Optional[datetime.datetime]:
    tr = (time_range or "all").strip().lower()
    if tr in ("30d", "30"):
        return datetime.datetime.now(datetime.timezone.utc) - datetime.timedelta(days=30)
    if tr in ("90d", "90"):
        return datetime.datetime.now(datetime.timezone.utc) - datetime.timedelta(days=90)
    return None


def _cohort_parse_dob_age(dob_raw) -> Optional[int]:
    """Full years from DOB; None if missing or unparseable."""
    if dob_raw is None:
        return None
    s = str(dob_raw).strip()
    if not s:
        return None
    parsed_date = None
    for fmt in ("%Y-%m-%d", "%m/%d/%Y", "%d/%m/%Y"):
        try:
            parsed_date = datetime.datetime.strptime(s[:10], fmt).date()
            break
        except ValueError:
            continue
    if parsed_date is None:
        try:
            parsed_date = datetime.date.fromisoformat(s[:10])
        except ValueError:
            return None
    today = datetime.date.today()
    age = today.year - parsed_date.year - (
        (today.month, today.day) < (parsed_date.month, parsed_date.day)
    )
    if age < 0 or age > 125:
        return None
    return age


def _cohort_age_bucket(age: Optional[int]) -> str:
    """Labels aligned with nevedal_lab_cohort.html checkboxes (plus Under 18 / Unknown)."""
    if age is None:
        return "Unknown"
    if age < 18:
        return "Under 18"
    if age < 26:
        return "18-25"
    if age < 36:
        return "26-35"
    if age < 51:
        return "36-50"
    return "51+"


def _dyad_pearson_series(x: List[float], y: List[float]) -> Optional[float]:
    """Pearson r for same-length sequences; None if undefined."""
    n = len(x)
    if n < 2 or len(y) != n:
        return None
    mx = sum(x) / n
    my = sum(y) / n
    num = sum((x[i] - mx) * (y[i] - my) for i in range(n))
    dxe = sum((x[i] - mx) ** 2 for i in range(n)) ** 0.5
    dye = sum((y[i] - my) ** 2 for i in range(n)) ** 0.5
    if dxe < 1e-12 or dye < 1e-12:
        return None
    return num / (dxe * dye)


def _dyad_aligned_slices(
    a: List[float], b: List[float], lag: int
) -> Tuple[Optional[List[float]], Optional[List[float]]]:
    """Align series a, b with integer lag (positive: b delayed relative to a)."""
    if lag > 0:
        if len(a) <= lag:
            return None, None
        aa, bb = a[:-lag], b[lag:]
    elif lag < 0:
        lag_abs = -lag
        if len(b) <= lag_abs:
            return None, None
        aa, bb = a[lag_abs:], b[:-lag_abs]
    else:
        aa, bb = a, b
    m = min(len(aa), len(bb))
    if m < 2:
        return None, None
    return aa[:m], bb[:m]


def _dyad_crosscorr_peak_lag(a: List[float], b: List[float], max_lag: int) -> Optional[int]:
    """Lag (in samples) at maximum |Pearson| over overlapping windows."""
    best_r: Optional[float] = None
    best_lag: Optional[int] = None
    for L in range(-max_lag, max_lag + 1):
        sa, sb = _dyad_aligned_slices(a, b, L)
        if sa is None or sb is None:
            continue
        r = _dyad_pearson_series([float(sa[i]) for i in range(len(sa))], [float(sb[i]) for i in range(len(sb))])
        if r is None:
            continue
        if best_r is None or abs(r) > abs(best_r):
            best_r = r
            best_lag = L
    return best_lag


async def _cohort_nevedal_first_last_c_emo(conn, user_ids: List, since: Optional[datetime.datetime]):
    """First and last c_emo per user in nevedal_metrics (optionally since UTC). Keys: str(uuid)."""
    first_map: Dict[str, float] = {}
    last_map: Dict[str, float] = {}
    if not user_ids:
        return first_map, last_map
    try:
        rows_first = await conn.fetch(
            """
            SELECT DISTINCT ON (user_id) user_id::text AS uid, c_emo::float8 AS c_emo
            FROM nevedal_metrics
            WHERE user_id = ANY($1::uuid[])
              AND c_emo IS NOT NULL
              AND ($2::timestamptz IS NULL OR recorded_at >= $2)
            ORDER BY user_id, recorded_at ASC
            """,
            user_ids,
            since,
        )
        for r in rows_first:
            if r["c_emo"] is not None:
                first_map[r["uid"]] = float(r["c_emo"])
        rows_last = await conn.fetch(
            """
            SELECT DISTINCT ON (user_id) user_id::text AS uid, c_emo::float8 AS c_emo
            FROM nevedal_metrics
            WHERE user_id = ANY($1::uuid[])
              AND c_emo IS NOT NULL
              AND ($2::timestamptz IS NULL OR recorded_at >= $2)
            ORDER BY user_id, recorded_at DESC
            """,
            user_ids,
            since,
        )
        for r in rows_last:
            if r["c_emo"] is not None:
                last_map[r["uid"]] = float(r["c_emo"])
    except Exception as e:
        logging.getLogger("bridge").warning("cohort nevedal first/last fetch failed: %s", e)
    return first_map, last_map


